/**
 * The tags one instance carries, keyed by tag name. Returns undefined when the
 * instance cannot be read, either because it is gone or because the account it
 * lives in is not one we can assume a role into.
 */
export const getInstanceTags = async (
    region: string,
    creds,
    instanceId: string,
): Promise<Record<string, string>> => {
    try {
        const ec2Client = new EC2Client({ region, credentials: creds });
        const response = await ec2Client.send(new DescribeInstancesCommand({ InstanceIds: [instanceId] }));
        const instance = (response?.Reservations ?? []).flatMap(({ Instances }) => Instances ?? [])[0];
        if (!instance) {
            return undefined;
        }
        return (instance.Tags ?? []).reduce((tags, { Key, Value }) => ({ ...tags, [Key]: Value }), {});
    } catch (err) {
        return undefined;
    }
};
