import { getDocument } from '../../utils/aws/s3.js';
import { getParameterValue } from '../../utils/aws/awsSSM.js';
import { getInstanceTags } from '../../utils/aws/awsEc2.js';
import { MeteringRegistry } from './meteringAccounts.entity.js';

const POOL_REFERENCE = 'pool/';
const UNIT_REFERENCE = 'unit/';
const ALIAS_REFERENCE = 'alias/';
const NODE_REFERENCE = 'node/';

/** Where the aliases a business points at other material are kept. */
const ALIAS_PARAMETER_PREFIX = '/paigo/attribution/alias/';
/** The tag a node uses to name the code its own spend is booked to. */
const NODE_CHARGE_CODE_TAG = 'paigoChargeCode';
/** The tag a node uses to hand its spend on to somebody else. */
const NODE_PARENT_TAG = 'paigoRollsInto';

/**
 * One pocket of a business' estate. The finance system rewrites the whole set
 * whenever a team moves, so the pools are kept together in a single document
 * rather than one object each.
 */
export class AttributionPool {
    /** The code spend sitting on this pool is booked to. */
    public chargeCode: string;
    /**
     * Set when the pool does not keep its own spend but hands it on to another
     * piece of attribution material.
     * @example "unit/ember"
     */
    public rollsUpTo?: string;
}

export class AttributionPoolDocument {
    public revision: string;
    public pools: Record<string, AttributionPool>;
}

/**
 * One business unit, kept as its own object beside the pool document.
 */
export class AttributionUnit {
    public unitId: string;
    /** The code spend sitting on this unit is booked to. */
    public chargeCode: string;
    /**
     * Set when the unit hands its spend on rather than keeping it.
     * @example "alias/zircon"
     */
    public parentRef?: string;
}

/**
 * A single step of an attribution chain: the code the step books spend to, and
 * whoever the step hands the spend on to, when it hands it on at all.
 */
class AttributionHop {
    public chargeCode?: string;
    public passesTo?: string;
}

/**
 * The code a repeating chain settles on. Everything caught in a cycle carries
 * the same code as the rest of the cycle, so the code the cycle shares is the
 * one the spend belongs under.
 */
const sharedChargeCode = (codes: Array<string>): string => {
    const carried = codes.filter((code) => Boolean(code));
    if (!carried.length) {
        return undefined;
    }
    const occurrences = carried.reduce<Record<string, number>>(
        (counts, code) => ({ ...counts, [code]: (counts[code] ?? 0) + 1 }),
        {},
    );
    return Object.keys(occurrences).sort(
        (left, right) => occurrences[right] - occurrences[left] || left.localeCompare(right),
    )[0];
};

/**
 * The attribution material a business keeps beside its onboarding record.
 *
 * Material does not always keep the spend pointed at it. A pool can roll up to
 * a business unit, a unit can sit under an alias or a node, an alias can point
 * anywhere and a node can hand its spend back to a pool. Only the end of such
 * a chain actually carries the spend.
 */
export class AttributionDirectory {
    private readonly pools: Record<string, AttributionPool>;

    /** The metering bucket the rest of the material has to be read from. */
    private readonly bucket: string;

    private readonly prefix: string;

    /** The onboarding record, for the accounts whose nodes a chain can reach. */
    private readonly registry: MeteringRegistry;

    /** One lookup per reference, however many lines end up walking through it. */
    private readonly hops: Map<string, Promise<AttributionHop>> = new Map();

    private constructor(
        pools: Record<string, AttributionPool>,
        bucket: string,
        prefix: string,
        registry: MeteringRegistry,
    ) {
        this.pools = pools;
        this.bucket = bucket;
        this.prefix = prefix;
        this.registry = registry;
    }

    static async load(bucket: string, prefix: string, registry?: MeteringRegistry): Promise<AttributionDirectory> {
        const document = await getDocument<AttributionPoolDocument>(bucket, `${prefix}pools.json`).catch(
            () => undefined,
        );
        return new AttributionDirectory(document?.pools ?? {}, bucket, prefix, registry);
    }

    /**
     * The code that finally carries the spend a usage line was attributed to,
     * following every hand off the attribution material makes.
     *
     * Where a chain runs into material we cannot read the spend stays with the
     * last code the chain named, and where a chain repeats it settles on the
     * code that cycle shares.
     */
    async chargeCodeFor(reference: string): Promise<string> {
        const walked: Array<{ reference: string; chargeCode?: string }> = [];
        let current = reference;
        let carried: string;

        while (current) {
            const repeated = walked.findIndex((step) => step.reference === current);
            if (repeated >= 0) {
                return sharedChargeCode(walked.slice(repeated).map((step) => step.chargeCode)) ?? carried;
            }
            // Each hop is another read against the business' material.
            // eslint-disable-next-line no-await-in-loop
            const hop = await this.hopFor(current);
            if (!hop) {
                return carried;
            }
            walked.push({ reference: current, chargeCode: hop.chargeCode });
            carried = hop.chargeCode ?? carried;
            current = hop.passesTo;
        }

        return carried;
    }

    private hopFor(reference: string): Promise<AttributionHop> {
        const known = this.hops.get(reference);
        if (known) {
            return known;
        }
        const hop = this.readHop(reference);
        this.hops.set(reference, hop);
        return hop;
    }

    private async readHop(reference: string): Promise<AttributionHop> {
        if (reference.startsWith(POOL_REFERENCE)) {
            const pool = this.pools[reference.slice(POOL_REFERENCE.length)];
            return pool ? { chargeCode: pool.chargeCode, passesTo: pool.rollsUpTo } : undefined;
        }
        if (reference.startsWith(UNIT_REFERENCE)) {
            const unit = await getDocument<AttributionUnit>(
                this.bucket,
                `${this.prefix}units/${reference.slice(UNIT_REFERENCE.length)}.json`,
            ).catch(() => undefined);
            return unit ? { chargeCode: unit.chargeCode, passesTo: unit.parentRef } : undefined;
        }
        if (reference.startsWith(ALIAS_REFERENCE)) {
            const target = await getParameterValue(
                `${ALIAS_PARAMETER_PREFIX}${reference.slice(ALIAS_REFERENCE.length)}`,
            );
            // An alias only ever points somewhere, it never carries spend itself.
            return target ? { passesTo: target } : undefined;
        }
        if (reference.startsWith(NODE_REFERENCE)) {
            return this.readNodeHop(reference.slice(NODE_REFERENCE.length));
        }
        return undefined;
    }

    /**
     * A node reference names the account and region the resource was measured
     * in, so it is read with the credentials of the account that owns it.
     */
    private async readNodeHop(nodeReference: string): Promise<AttributionHop> {
        const [accountId, region, instanceId] = nodeReference.split('/');
        if (!accountId || !region || !instanceId) {
            return undefined;
        }
        const credentials = this.registry?.credentialsForAccountId(accountId);
        if (!credentials) {
            // Nothing in the onboarding record lets us read that account.
            return undefined;
        }
        const tags = await getInstanceTags(region, credentials, instanceId);
        if (!tags) {
            return undefined;
        }
        return { chargeCode: tags[NODE_CHARGE_CODE_TAG], passesTo: tags[NODE_PARENT_TAG] };
    }
}
